109	            BigDecimal overdue = ZERO;
110	            boolean keptFigure = false;
111	            for (Claim claim : sheetClaims) {
112	                if (!claim.getPersonId().equals(person.getId()) || !countsClaimed(claim, person, today)) {
113	                    continue;
114	                }
115	                if (claim.getCorrects() == null || claim.getCorrects().isEmpty()) {
116	                    // a claim that corrects another is left out of claimed
117	                    claimed = claimed.add(claim.getAmount());
118	                }
119	                BigDecimal kept = claim.getSettledDue() != null ? claim.getSettledDue()
120	                        : claim.isBound() ? claim.getStatedDue() : null;
121	                BigDecimal figure = null;
122	                if (kept != null) {
123	                    keptFigure = true;
124	                    figure = charged(sheet, claim, person, kept);
125	                } else if (!claim.isBound()) {
126	                    // a claim priced at the grade in force on its date keeps a figure too
127	                    BigDecimal live = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
128	                            .map(rate -> rated(sheet, claim, sheetClaims, rate))
129	                            .orElse(null);
130	                    if (live != null) {
131	                        keptFigure = true;
132	                        figure = charged(sheet, claim, person, live);
133	                    }
134	                }
135	                if (figure != null) {
136	                    due = due.add(figure);
137	                    if (overdue(sheet, claim, person, today)) {
138	                        overdue = overdue.add(figure);
139	                    }
140	                }
141	            }
142	            boolean rated = today != null && inForce(sheetRates, person.gradeOn(today), today).isPresent();
143	            BigDecimal personDue = rated || keptFigure ? capped(sheet, due) : null;
144	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue, overdue));
145	            claimedTotal = claimedTotal.add(claimed);
146	            overdues.add(overdue);
147	            if (personDue != null) {
148	                dues.add(personDue);
149	            }
150	        }
151	        return new Snapshot(figures, claimedTotal, trimmed(dues), trimmed(overdues));
152	    }
