190	    /** Each person on a sheet, now or as it stood at the end of a date, in list order, with their figures in
191	     *  its snapshot then. */
192	    public List<Member> members(String sheetId, LocalDate date, Snapshot snapshot) {
193	        List<Person> sheetPeople = date == null ? people.findBySheetIdOrderByPositionAscIdAsc(sheetId)
194	                : asOf.people(sheetId, date);
195	        List<Member> members = new ArrayList<>();
196	        for (Person person : sheetPeople) {
197	            Figures figures = snapshot.people().get(person.getId());
198	            if (figures == null) {
199	                continue;
200	            }
201	            List<String> names = new ArrayList<>(List.of(person.getName()));
202	            names.addAll(person.getAliases());
203	            members.add(new Member(names, figures.dueTotal(), figures.overdueTotal()));
204	        }
205	        return members;
206	    }
