208	    /** A sheet's breakdown by grade and status, now or as it stood at the end of a date, from its snapshot then. */
209	    public Breakdown breakdown(String sheetId, LocalDate date, Snapshot snapshot) {
210	        LocalDate today = (date == null ? sheets.findById(sheetId) : Optional.of(asOf.sheet(sheetId, date)))
211	                .map(Sheet::getToday).orElse(null);
212	        List<Person> sheetPeople = date == null ? people.findBySheetIdOrderByPositionAscIdAsc(sheetId)
213	                : asOf.people(sheetId, date);
214	        List<Claim> sheetClaims = date == null ? claims.findBySheetIdOrderByIdDesc(sheetId) : asOf.claims(sheetId, date);
215	        Map<String, BigDecimal> gradeDues = new LinkedHashMap<>();
216	        for (Person person : sheetPeople) {
217	            Figures figures = snapshot.people().get(person.getId());
218	            if (person.isRetired() || figures == null || figures.dueTotal() == null) {
219	                continue;
220	            }
221	            gradeDues.merge(person.gradeOn(today == null ? LocalDate.MAX : today), figures.dueTotal(), BigDecimal::add);
222	        }
223	        Map<ClaimStatus, Integer> statusCounts = new LinkedHashMap<>();
224	        sheetClaims.forEach(c -> statusCounts.merge(c.getStatus(), 1, Integer::sum));
225	        return new Breakdown(gradeDues, statusCounts);
226	    }
