228	    /** People's figures added up, leaving out the single highest and the single lowest when there are three
229	     *  or more. */
230	    static BigDecimal trimmed(List<BigDecimal> figures) {
231	        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
232	        if (figures.size() < 3) {
233	            return sum;
234	        }
235	        BigDecimal max = figures.stream().max(BigDecimal::compareTo).orElseThrow();
236	        BigDecimal min = figures.stream().min(BigDecimal::compareTo).orElseThrow();
237	        return sum.subtract(max).subtract(min);
238	    }
