240	    /** Each person's due-total of their claims due by a day from one date to another, both inclusive, by person
241	     *  id, every person on the sheet in list order, as the screen shows a person's for a
242	     *  period: a claim counts by the status it had at the end of the last day, as its status log records
243	     *  it (one added after then does not), unless a hold or a deferral leaves it out now; each counts its
244	     *  due as shown now: its settled due, else the figure its statement bound, else its live due, an
245	     *  overdue claim's late charge on top, at least the floor (a claim with no figure adds nothing). */
246	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
247	        Optional<Sheet> sheet = sheets.findById(sheetId);
248	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
249	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
250	        Map<Long, Person> byId = new LinkedHashMap<>();
251	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
252	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
253	            byId.put(p.getId(), p);
254	            totals.put(p.getId(), ZERO);
255	        });
256	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
257	        for (Claim claim : sheetClaims) {
258	            Person person = byId.get(claim.getPersonId());
259	            if (person == null || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)
260	                    || !countsAt(claim, to) || heldOut(claim, person, today) || claim.deferredOn(today)) {
261	                continue;
262	            }
263	            BigDecimal due;
264	            if (claim.getSettledDue() != null) {
265	                due = claim.getSettledDue();
266	            } else if (claim.isBound()) {
267	                due = claim.getStatedDue();
268	            } else {
269	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
270	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
271	                        .orElse(null);
272	            }
273	            if (due != null) {
274	                totals.merge(person.getId(), charged(sheet, claim, person, due), BigDecimal::add);
275	            }
276	        }
277	        return totals;
278	    }
