280	    /** Each person's carried figure for a period, by person id, every person on the sheet in list order, as the
281	     *  screen shows it while the period is open: the due (as {@link #dueBetweenByPerson} counts it) of their
282	     *  claims not left out now by a hold or a deferral whose due-by falls in one of the sheet's periods ending
283	     *  before this one starts, and that were still OPEN or PENDING at the end of this period's last day, as
284	     *  their status log records it; and their opening balance for the period on top. */
285	    public Map<Long, BigDecimal> carriedByPerson(String sheetId, Period period, List<Period> sheetPeriods) {
286	        Optional<Sheet> sheet = sheets.findById(sheetId);
287	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
288	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
289	        Map<Long, Person> byId = new LinkedHashMap<>();
290	        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
291	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
292	            byId.put(p.getId(), p);
293	            carried.put(p.getId(), ZERO);
294	        });
295	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
296	        for (Claim claim : sheetClaims) {
297	            Person person = byId.get(claim.getPersonId());
298	            if (person == null || claim.getDueBy() == null || heldOut(claim, person, today) || claim.deferredOn(today)) {
299	                continue;
300	            }
301	            Optional<Period> own = sheetPeriods.stream().filter(p -> p.contains(claim.getDueBy())).findFirst();
302	            if (own.isEmpty() || !own.get().getToDate().isBefore(period.getFromDate())) {
303	                continue;
304	            }
305	            ClaimStatus status = statusAt(claim, period.getToDate());
306	            if (status == null || !status.isOpen()) {
307	                continue;
308	            }
309	            BigDecimal due;
310	            if (claim.getSettledDue() != null) {
311	                due = claim.getSettledDue();
312	            } else if (claim.isBound()) {
313	                due = claim.getStatedDue();
314	            } else {
315	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
316	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
317	                        .orElse(null);
318	            }
319	            if (due != null) {
320	                carried.merge(person.getId(), charged(sheet, claim, person, due), BigDecimal::add);
321	            }
322	        }
323	        period.getOpenings().forEach((id, opening) -> carried.computeIfPresent(id, (k, c) -> c.add(opening)));
324	        return carried;
325	    }
