327	    /** Each person's open figure at the end of a day, by person id, every person on the sheet in list order: the
328	     *  due (as {@link #carriedByPerson} counts it) of their claims not left out now by a hold or a deferral whose
329	     *  due-by falls in one of the given periods, and that were OPEN or PENDING at the end of the day, as their
330	     *  status log records it. */
331	    public Map<Long, BigDecimal> openByPerson(String sheetId, List<Period> inPeriods, LocalDate day) {
332	        Optional<Sheet> sheet = sheets.findById(sheetId);
333	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
334	        List<Rate> sheetRates = rates.findWithAncestors(sheetId, sheets.ancestors(sheetId));
335	        Map<Long, Person> byId = new LinkedHashMap<>();
336	        Map<Long, BigDecimal> open = new LinkedHashMap<>();
337	        people.findBySheetIdOrderByPositionAscIdAsc(sheetId).forEach(p -> {
338	            byId.put(p.getId(), p);
339	            open.put(p.getId(), ZERO);
340	        });
341	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
342	        for (Claim claim : sheetClaims) {
343	            Person person = byId.get(claim.getPersonId());
344	            if (person == null || claim.getDueBy() == null || heldOut(claim, person, today) || claim.deferredOn(today)
345	                    || inPeriods.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
346	                continue;
347	            }
348	            ClaimStatus status = statusAt(claim, day);
349	            if (status == null || !status.isOpen()) {
350	                continue;
351	            }
352	            BigDecimal due;
353	            if (claim.getSettledDue() != null) {
354	                due = claim.getSettledDue();
355	            } else if (claim.isBound()) {
356	                due = claim.getStatedDue();
357	            } else {
358	                due = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate(), claim)
359	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
360	                        .orElse(null);
361	            }
362	            if (due != null) {
363	                open.merge(person.getId(), charged(sheet, claim, person, due), BigDecimal::add);
364	            }
365	        }
366	        return open;
367	    }
