391	    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
392	    public void recordChanges(String sheetId, String user, Snapshot before) {
393	        Snapshot after = take(sheetId);
394	        String prefix = " sheet=" + sheetId + " by=" + user;
395	        after.people().forEach((id, now) -> {
396	            Figures was = before.people().get(id);
397	            if (was == null || was.claimed().compareTo(now.claimed()) != 0
398	                    || !sameDue(was.dueTotal(), now.dueTotal())
399	                    || was.overdueTotal().compareTo(now.overdueTotal()) != 0) {
400	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
401	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal())
402	                        + " overdue-total=" + now.overdueTotal().toPlainString());
403	            }
404	        });
405	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
406	                || before.dueTotal().compareTo(after.dueTotal()) != 0
407	                || before.overdueTotal().compareTo(after.overdueTotal()) != 0) {
408	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
409	                    + " due-total=" + after.dueTotal().toPlainString()
410	                    + " overdue-total=" + after.overdueTotal().toPlainString());
411	        }
412	        recordAlerts(sheetId, prefix, before, after);
413	    }
