415	    /** Record, once the change commits, an ALERT line for each person whose due-total went from at or below the
416	     *  sheet's alert threshold (or none, or new to the sheet) to above it, in the list order; none when the
417	     *  threshold is off. */
418	    private void recordAlerts(String sheetId, String prefix, Snapshot before, Snapshot after) {
419	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
420	        if (threshold == null) {
421	            return;
422	        }
423	        after.people().forEach((id, now) -> {
424	            Figures was = before == null ? null : before.people().get(id);
425	            if (above(now.dueTotal(), threshold) && (was == null || !above(was.dueTotal(), threshold))) {
426	                audit.recordOnCommit("ALERT" + prefix + " name=" + now.name() + " due-total=" + show(now.dueTotal()));
427	            }
428	        });
429	    }
