435	    /** Whether a claim counts toward claimed: its status counts, it is not left out by its person's
436	     *  retirement (a hold leaves it in), and it is not deferred past the sheet's today. */
437	    private static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
438	        return claim.getStatus().counts() && !retiredOut(claim, person, today) && !claim.deferredOn(today);
439	    }
