441	    /** Whether a claim counted by the status it had at the end of a day, as its status log records it:
442	     *  its latest line dated on or before it; not when it was added after it. A claim with no log counts
443	     *  by its status now. */
444	    private static boolean countsAt(Claim claim, LocalDate day) {
445	        ClaimStatus status = statusAt(claim, day);
446	        return status != null && status.counts();
447	    }
