449	    /** The status a claim had at the end of a day, as its status log records it: its latest line dated on or
450	     *  before it; none when it was added after it. A claim with no log has its status now. */
451	    private static ClaimStatus statusAt(Claim claim, LocalDate day) {
452	        List<StatusChange> log = claim.getStatusLog();
453	        if (log.isEmpty()) {
454	            return claim.getStatus();
455	        }
456	        ClaimStatus status = null;
457	        for (StatusChange change : log) {
458	            if (!change.getOn().isAfter(day)) {
459	                status = change.getStatus();
460	            }
461	        }
462	        return status;
463	    }
