465	    /** Whether a claim is overdue: OPEN or PENDING, not deferred, with its due-by plus the grace days of its
466	     *  person's grade in force on its date before the sheet's today. */
467	    private static boolean overdue(Optional<Sheet> sheet, Claim claim, Person person, LocalDate today) {
468	        return claim.getStatus().isOpen() && !claim.deferredOn(today) && today != null && claim.getDueBy() != null
469	                && lateFrom(sheet, claim, person).isBefore(today);
470	    }
471	
472	    /** The date a claim's lateness runs from: its due-by plus the grace days in force on its date of its
473	     *  person's grade in force then. */
474	    public static LocalDate lateFrom(Optional<Sheet> sheet, Claim claim, Person person) {
475	        String grade = person == null ? null : person.gradeOn(claim.getDate());
476	        return sheet.map(s -> s.lateFrom(claim.getDueBy(), grade, claim.getDate())).orElse(claim.getDueBy());
477	    }
