479	    /** Whether a retirement leaves a claim out of claimed: it is OPEN or PENDING, bound by no statement, and
480	     *  its person's retirement date is reached on the sheet's today. */
481	    private static boolean retiredOut(Claim claim, Person person, LocalDate today) {
482	        return person != null && claim.getStatus().isOpen() && !claim.isBound() && person.retiredBy(today);
483	    }
484	
485	    /** Whether a retirement leaves a claim out of the live totals: it is OPEN or PENDING, bound by no
486	     *  statement, and its person's retirement date is reached on the sheet's today. A hold no longer does:
487	     *  it only takes a person's cut out of the pools. */
488	    public static boolean heldOut(Claim claim, Person person, LocalDate today) {
489	        return retiredOut(claim, person, today);
490	    }
