492	    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
493	     *  the sheet (half to even with no sheet). */
494	    public static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
495	        LocalDate on = roundingDate(claim, sheetClaims);
496	        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
497	                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
498	    }
