500	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
501	     *  corrects (the claim of the same person with that number), its own when that is not found. */
502	    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
503	        if (!claim.isCorrection()) {
504	            return claim.getDate();
505	        }
506	        return sheetClaims.stream()
507	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
508	                .findFirst().map(Claim::getDate).orElse(claim.getDate());
509	    }
510	
511	    /** A claim's due from its figure: at least the sheet's floor in force on its date, then its late charge,
512	     *  worked out on that floored figure, on top while it is OPEN or PENDING (only those go overdue). A settled claim's due is frozen (it
513	     *  already holds the charge and floor fixed when it was settled), as is a bound one's (its statement bound
514	     *  the due as shown then, charge and floor included); a correction has neither late charge nor floor, and a
515	     *  waived claim no late charge. */
516	    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, Person person, BigDecimal figure) {
517	        if (claim.getSettledDue() != null || claim.isBound() || claim.isCorrection()) {
518	            return figure;
519	        }
520	        return sheet.map(s -> {
521	                    BigDecimal floored = s.floored(figure, claim.getDate());
522	                    return claim.getStatus().isOpen() && !claim.isWaived()
523	                            ? floored.add(s.lateCharge(floored, lateFrom(sheet, claim, person), claim.getDate())) : floored;
524	                })
525	                .orElse(figure);
526	    }
