528	    /** A person's due-total at most the sheet's cap. */
529	    private static BigDecimal capped(Optional<Sheet> sheet, BigDecimal dueTotal) {
530	        return sheet.map(s -> s.capped(dueTotal)).orElse(dueTotal);
531	    }
532	
533	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
534	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
535	    }
536	
537	    private static String show(BigDecimal due) {
538	        return due == null ? "n/a" : due.toPlainString();
539	    }
