541	    /** The grade's rate in force on a date for a claim: as {@link #inForce(List, String, LocalDate)}, each rate
542	     *  as it applies to the claim (a forward-only rate not to a claim already on the sheet when it was saved,
543	     *  which keeps what applied to it). */
544	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date, Claim claim) {
545	        List<Rate> forClaim = new ArrayList<>();
546	        sheetRates.forEach(r -> r.forClaim(claim.getId()).ifPresent(forClaim::add));
547	        return inForce(forClaim, grade, date);
548	    }
549	
550	    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
551	     *  when the date is after that rate's to-date. The rates may be a sheet's followed by its ancestors',
552	     *  nearest first: the first sheet, in that order, with a rate of the grade in force then gives it. */
553	    public static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
554	        Set<String> sheetIds = new LinkedHashSet<>();
555	        sheetRates.forEach(r -> sheetIds.add(r.getSheetId()));
556	        for (String sheetId : sheetIds) {
557	            Optional<Rate> found = inForceOn(sheetRates, sheetId, grade, date);
558	            if (found.isPresent()) {
559	                return found;
560	            }
561	        }
562	        return Optional.empty();
